-- D1 rows_read reduction: season-scoped lookups must not scan whole tables.
CREATE INDEX IF NOT EXISTS predictions_season_locked_idx ON predictions(season_id, is_locked);
CREATE INDEX IF NOT EXISTS score_snapshots_season_user_total_idx ON score_snapshots(season_id, user_id, total_score);

-- Public aggregates are served from one row per key (lib/computed-cache.ts).
CREATE TABLE IF NOT EXISTS computed_cache (
  key TEXT PRIMARY KEY NOT NULL,
  value TEXT NOT NULL,
  computed_at INTEGER NOT NULL,
  -- data_changes.changed_at observed when the compute started
  basis INTEGER NOT NULL,
  claimed_at INTEGER
);

-- Change clocks (epoch ms): id = season year for writes to that season's data,
-- id = 0 for writes that affect every season (seasons, users). A cached result
-- is fresh while the clocks it depends on have not moved (lib/computed-cache.ts),
-- so a standings update for 2026 does not recompute 2014-2025 results.
-- Drafts (unlocked predictions and their picks) and new sign-ups do not count,
-- so user activity does not multiply recomputes. The WHERE keeps bulk imports
-- at one write per clock per ms, not one per row.
CREATE TABLE IF NOT EXISTS data_changes (
  id INTEGER PRIMARY KEY NOT NULL,
  changed_at INTEGER NOT NULL
);
CREATE TRIGGER IF NOT EXISTS seasons_insert_marks_cache_stale AFTER INSERT ON seasons BEGIN INSERT INTO data_changes (id, changed_at) VALUES (COALESCE(0, 0), CAST(unixepoch('subsec') * 1000 AS INTEGER)) ON CONFLICT (id) DO UPDATE SET changed_at = excluded.changed_at WHERE data_changes.changed_at < excluded.changed_at; END;
CREATE TRIGGER IF NOT EXISTS seasons_update_marks_cache_stale AFTER UPDATE ON seasons BEGIN INSERT INTO data_changes (id, changed_at) VALUES (COALESCE(0, 0), CAST(unixepoch('subsec') * 1000 AS INTEGER)) ON CONFLICT (id) DO UPDATE SET changed_at = excluded.changed_at WHERE data_changes.changed_at < excluded.changed_at; END;
CREATE TRIGGER IF NOT EXISTS seasons_delete_marks_cache_stale AFTER DELETE ON seasons BEGIN INSERT INTO data_changes (id, changed_at) VALUES (COALESCE(0, 0), CAST(unixepoch('subsec') * 1000 AS INTEGER)) ON CONFLICT (id) DO UPDATE SET changed_at = excluded.changed_at WHERE data_changes.changed_at < excluded.changed_at; END;
CREATE TRIGGER IF NOT EXISTS users_update_marks_cache_stale AFTER UPDATE ON users BEGIN INSERT INTO data_changes (id, changed_at) VALUES (COALESCE(0, 0), CAST(unixepoch('subsec') * 1000 AS INTEGER)) ON CONFLICT (id) DO UPDATE SET changed_at = excluded.changed_at WHERE data_changes.changed_at < excluded.changed_at; END;
CREATE TRIGGER IF NOT EXISTS users_delete_marks_cache_stale AFTER DELETE ON users BEGIN INSERT INTO data_changes (id, changed_at) VALUES (COALESCE(0, 0), CAST(unixepoch('subsec') * 1000 AS INTEGER)) ON CONFLICT (id) DO UPDATE SET changed_at = excluded.changed_at WHERE data_changes.changed_at < excluded.changed_at; END;
CREATE TRIGGER IF NOT EXISTS actual_team_standings_insert_marks_cache_stale AFTER INSERT ON actual_team_standings BEGIN INSERT INTO data_changes (id, changed_at) VALUES (COALESCE((SELECT year FROM seasons WHERE id = NEW.season_id), 0), CAST(unixepoch('subsec') * 1000 AS INTEGER)) ON CONFLICT (id) DO UPDATE SET changed_at = excluded.changed_at WHERE data_changes.changed_at < excluded.changed_at; END;
CREATE TRIGGER IF NOT EXISTS actual_team_standings_update_marks_cache_stale AFTER UPDATE ON actual_team_standings BEGIN INSERT INTO data_changes (id, changed_at) VALUES (COALESCE((SELECT year FROM seasons WHERE id = NEW.season_id), 0), CAST(unixepoch('subsec') * 1000 AS INTEGER)) ON CONFLICT (id) DO UPDATE SET changed_at = excluded.changed_at WHERE data_changes.changed_at < excluded.changed_at; INSERT INTO data_changes (id, changed_at) VALUES (COALESCE((SELECT year FROM seasons WHERE id = OLD.season_id), 0), CAST(unixepoch('subsec') * 1000 AS INTEGER)) ON CONFLICT (id) DO UPDATE SET changed_at = excluded.changed_at WHERE data_changes.changed_at < excluded.changed_at; END;
CREATE TRIGGER IF NOT EXISTS actual_team_standings_delete_marks_cache_stale AFTER DELETE ON actual_team_standings BEGIN INSERT INTO data_changes (id, changed_at) VALUES (COALESCE((SELECT year FROM seasons WHERE id = OLD.season_id), 0), CAST(unixepoch('subsec') * 1000 AS INTEGER)) ON CONFLICT (id) DO UPDATE SET changed_at = excluded.changed_at WHERE data_changes.changed_at < excluded.changed_at; END;
