CREATE TRIGGER IF NOT EXISTS predictions_insert_marks_cache_stale AFTER INSERT ON predictions WHEN NEW.is_locked = 1 BEGIN INSERT INTO data_changes (id, changed_at) VALUES (COALESCE((SELECT year FROM seasons WHERE id = NEW.season_id), 0), CAST(unixepoch('subsec') * 1000 AS INTEGER)) ON CONFLICT (id) DO UPDATE SET changed_at = excluded.changed_at WHERE data_changes.changed_at < excluded.changed_at; END;
CREATE TRIGGER IF NOT EXISTS predictions_update_marks_cache_stale AFTER UPDATE ON predictions WHEN NEW.is_locked = 1 OR OLD.is_locked = 1 BEGIN INSERT INTO data_changes (id, changed_at) VALUES (COALESCE((SELECT year FROM seasons WHERE id = NEW.season_id), 0), CAST(unixepoch('subsec') * 1000 AS INTEGER)) ON CONFLICT (id) DO UPDATE SET changed_at = excluded.changed_at WHERE data_changes.changed_at < excluded.changed_at; INSERT INTO data_changes (id, changed_at) VALUES (COALESCE((SELECT year FROM seasons WHERE id = OLD.season_id), 0), CAST(unixepoch('subsec') * 1000 AS INTEGER)) ON CONFLICT (id) DO UPDATE SET changed_at = excluded.changed_at WHERE data_changes.changed_at < excluded.changed_at; END;
CREATE TRIGGER IF NOT EXISTS predictions_delete_marks_cache_stale AFTER DELETE ON predictions WHEN OLD.is_locked = 1 BEGIN INSERT INTO data_changes (id, changed_at) VALUES (COALESCE((SELECT year FROM seasons WHERE id = OLD.season_id), 0), CAST(unixepoch('subsec') * 1000 AS INTEGER)) ON CONFLICT (id) DO UPDATE SET changed_at = excluded.changed_at WHERE data_changes.changed_at < excluded.changed_at; END;
CREATE TRIGGER IF NOT EXISTS ranking_picks_insert_marks_cache_stale AFTER INSERT ON ranking_picks WHEN (SELECT is_locked FROM predictions WHERE id = NEW.prediction_id) = 1 BEGIN INSERT INTO data_changes (id, changed_at) VALUES (COALESCE((SELECT s.year FROM predictions p JOIN seasons s ON s.id = p.season_id WHERE p.id = NEW.prediction_id), 0), CAST(unixepoch('subsec') * 1000 AS INTEGER)) ON CONFLICT (id) DO UPDATE SET changed_at = excluded.changed_at WHERE data_changes.changed_at < excluded.changed_at; END;
CREATE TRIGGER IF NOT EXISTS ranking_picks_update_marks_cache_stale AFTER UPDATE ON ranking_picks WHEN (SELECT is_locked FROM predictions WHERE id = NEW.prediction_id) = 1 OR (SELECT is_locked FROM predictions WHERE id = OLD.prediction_id) = 1 BEGIN INSERT INTO data_changes (id, changed_at) VALUES (COALESCE((SELECT s.year FROM predictions p JOIN seasons s ON s.id = p.season_id WHERE p.id = NEW.prediction_id), 0), CAST(unixepoch('subsec') * 1000 AS INTEGER)) ON CONFLICT (id) DO UPDATE SET changed_at = excluded.changed_at WHERE data_changes.changed_at < excluded.changed_at; INSERT INTO data_changes (id, changed_at) VALUES (COALESCE((SELECT s.year FROM predictions p JOIN seasons s ON s.id = p.season_id WHERE p.id = OLD.prediction_id), 0), CAST(unixepoch('subsec') * 1000 AS INTEGER)) ON CONFLICT (id) DO UPDATE SET changed_at = excluded.changed_at WHERE data_changes.changed_at < excluded.changed_at; END;
CREATE TRIGGER IF NOT EXISTS ranking_picks_delete_marks_cache_stale AFTER DELETE ON ranking_picks WHEN (SELECT is_locked FROM predictions WHERE id = OLD.prediction_id) = 1 BEGIN INSERT INTO data_changes (id, changed_at) VALUES (COALESCE((SELECT s.year FROM predictions p JOIN seasons s ON s.id = p.season_id WHERE p.id = OLD.prediction_id), 0), CAST(unixepoch('subsec') * 1000 AS INTEGER)) ON CONFLICT (id) DO UPDATE SET changed_at = excluded.changed_at WHERE data_changes.changed_at < excluded.changed_at; END;
